+      padding: 0.95rem 1rem;
+      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
+    }
+
+    input::placeholder {
+      color: #94a3b8;
+    }
+
+    input:focus {
+      outline: 3px solid var(--focus);
+      outline-offset: 2px;
+      border-color: var(--primary);
+      background: var(--surface);
