      border-radius: 1.5rem;
      box-shadow: 0 1.5rem 4rem rgba(15, 23, 42, 0.12);
      overflow: hidden;
    }

    .hero {
      background: linear-gradient(135deg, #1e3a8a, #2563eb);
      color: #ffffff;
      padding: 2.5rem;
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: #bfdbfe;
      font-size: 0.82rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 6vw, 3rem);
