    .intro {
      max-width: 32rem;
      margin: 1rem 0 0;
      color: #dbeafe;
      font-size: 1.05rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1.25rem;
      padding: 2rem;
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

