      font: inherit;
      padding: 0.95rem 1rem;
      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    input::placeholder {
      color: #94a3b8;
    }

    input:focus {
      outline: 3px solid var(--focus);
      outline-offset: 2px;
      border-color: var(--primary);
      background: var(--surface);
    }

    input[aria-invalid="true"] {
      border-color: var(--danger);
      background: var(--danger-bg);
    }

    .helper-text {
      margin: 0;
      color: var(--muted);
      font-size: 0.93rem;
      line-height: 1.45;
    }

    .validation-message {
      min-height: 1.35rem;
      margin: 0;
      color: var(--danger);
      font-size: 0.93rem;
      font-weight: 700;
      line-height: 1.45;
    }

    button {
      border: 0;
      border-radius: 999px;
      background: var(--primary);
      color: #ffffff;
      cursor: pointer;
      font: inherit;
      font-weight: 800;
      padding: 1rem 1.35rem;
      transition: background 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    button:hover {
      background: var(--primary-dark);
      transform: translateY(-1px);
      box-shadow: 0 0.75rem 1.5rem rgba(37, 99, 235, 0.22);
    }

    button:focus {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    @media (max-width: 40rem) {
      .hero,
      form {
        padding: 1.5rem;
      }
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const fields = [
      {
        id: "fullName",
        label: "Full name",
        type: "text",
        autocomplete: "name",
        placeholder: "Jane Cooper",
        required: true,
        requiredMessage: "Enter your full name."
      },
      {
        id: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        placeholder: "jane@example.com",
        required: true,
        requiredMessage: "Enter your email address.",
        formatMessage: "Enter a valid email address."
      },
      {
        id: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        placeholder: "+1 555 123 4567",
        required: false,
        helperText: "Optional. Use digits, spaces, parentheses, hyphens, or a leading plus sign, such as +1 555 123 4567.",
        formatMessage: "Enter a valid phone number or leave this field blank."
      }
    ];

    const values = {
      fullName: "",
      email: "",
      phone: ""
    };

    const errors = {
      fullName: "",
      email: "",
      phone: ""
    };

    function isValidEmail(value) {
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
    }

    function isValidPhone(value) {
      return /^\+?[0-9\s().-]{7,20}$/.test(value);
    }

    function validateField(field) {
      const value = values[field.id].trim();

      if (field.required && !value) {
        return field.requiredMessage;
      }

      if (field.id === "email" && value && !isValidEmail(value)) {
        return field.formatMessage;
      }

      if (field.id === "phone" && value && !isValidPhone(value)) {
        return field.formatMessage;
      }

      return "";
    }

    function FormField(field) {
      const requiredLabel = field.required ? '<span class="required" aria-hidden="true">*</span>' : "";
      const requiredText = field.required ? '<span class="sr-only"> required</span>' : "";
      const helperId = `${field.id}-helper`;
      const errorId = `${field.id}-error`;
      const describedBy = [field.helperText ? helperId : "", errorId].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${field.id}">${field.label} ${requiredLabel}${requiredText}</label>
          <input
            id="${field.id}"
            name="${field.id}"
            type="${field.type}"
            autocomplete="${field.autocomplete}"
            placeholder="${field.placeholder}"
            value="${values[field.id]}"
            ${field.required ? "required" : ""}
            aria-invalid="${errors[field.id] ? "true" : "false"}"
            aria-describedby="${describedBy}"
          >
          ${field.helperText ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>` : ""}
          <p class="validation-message" id="${errorId}" aria-live="polite">${errors[field.id]}</p>
        </div>
      `;
    }

    function SupportContactForm() {
      return `
        <section class="support-card" aria-labelledby="support-title">
          <div class="hero">
            <p class="eyebrow">Support request</p>
            <h1 id="support-title">How can we help?</h1>
            <p class="intro">Send your contact details and our support team will get back to you with the next steps.</p>
          </div>
          <form id="support-form" novalidate>
            ${fields.map(FormField).join("")}
            <button type="submit">Submit support request</button>
          </form>
        </section>
      `;
    }

    function render() {
      document.getElementById("app").innerHTML = SupportContactForm();

      fields.forEach((field) => {
        const input = document.getElementById(field.id);
        input.addEventListener("input", (event) => {
          values[field.id] = event.target.value;
          errors[field.id] = validateField(field);
          render();
          document.getElementById(field.id).focus();
        });
      });

      document.getElementById("support-form").addEventListener("submit", (event) => {
        event.preventDefault();
        fields.forEach((field) => {
          errors[field.id] = validateField(field);
        });
        render();

        const firstInvalid = fields.find((field) => errors[field.id]);
        if (firstInvalid) {
          document.getElementById(firstInvalid.id).focus();
        }
      });
    }

    render();
  </script>
</body>
</html>
