<body>
  <main id="app"></main>

  <script>
    const fields = [
      {
        id: "fullName",
        label: "Full name",
        type: "text",
        autocomplete: "name",
        placeholder: "Jane Cooper",
        required: true,
        requiredMessage: "Enter your full name."
      },
      {
        id: "email",
        label: "Email address",
        type: "email",
        autocomplete: "email",
        placeholder: "jane@example.com",
        required: true,
        requiredMessage: "Enter your email address.",
        formatMessage: "Enter a valid email address."
      },
      {
        id: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        placeholder: "+1 555 123 4567",
        required: false,
        helperText: "Optional. Use digits, spaces, parentheses, hyphens, or a leading plus sign, such as +1 555 123 4567.",
        formatMessage: "Enter a valid phone number or leave this field blank."
      }
    ];

    const values = {
      fullName: "",
      email: "",
      phone: ""
    };

    const errors = {
      fullName: "",
      email: "",
      phone: ""
    };

    function isValidEmail(value) {
      return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
    }

    function isValidPhone(value) {
      return /^\+?[0-9\s().-]{7,20}$/.test(value);
    }

    function escapeHtml(value) {
      return String(value)
        .replaceAll("&", "&amp;")
        .replaceAll('"', "&quot;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;");
    }

    function validateField(field) {
      const value = values[field.id].trim();

      if (field.required && !value) {
        return field.requiredMessage;
      }

      if (field.id === "email" && value && !isValidEmail(value)) {
        return field.formatMessage;
      }

      if (field.id === "phone" && value && !isValidPhone(value)) {
        return field.formatMessage;
      }

      return "";
    }

    function FormField(field) {
      const requiredLabel = field.required ? '<span class="required" aria-hidden="true">*</span>' : "";
      const requiredText = field.required ? '<span class="sr-only"> required</span>' : "";
